program:
app "Dose Times" pill mint
setting first time = 7:00 "First dose at"
setting gap num 1..24 = 8 "Hours between doses"
let n = floor(24 / gap)
let nowm = hour(now) * 60 + minute(now)
let firstm = hour(first) * 60 + minute(first)
let wait = min(0..n - 1, (firstm + it * gap * 60 - nowm) % 1440)
field first
field gap
"Next dose in" wait * 1m head
"Follow the exact instructions from your pharmacist." faint

program_before:
app "Meter" bolt plum
table reading units num 0..
let m0 = max(reading.units month)
let m1 = max(reading.units prev month)
let m2 = max(reading.units month of addmonths(today, -2))
"Units used this month" m0 - m1 big
"Last month" m1 - m2 "units" faint
if(m0 - m1 > m1 - m2, "More than last month", "Same or less than last month") color if(m0 - m1 > m1 - m2, warn, good)
form reading, "Enter meter reading"
list reading by day

